ayable contact in the CRM.\", \"parameters\": {\"properties\": {\"company\": {\"type\": \"string\"}}, \"required\": [\"company\"], \"type\": \"object\"}}}, {\"type\": \"function\", \"function\": {\"name\": \"remember\", \"description\": \"Store a fact so that later sessions know it.\\n\\n        Use a short, dotted key such as ``acme.billing_address``.\", \"parameters\": {\"properties\": {\"key\": {\"type\": \"string\"}, \"value\": {\"type\": \"string\"}}, \"required\": [\"key\", \"value\"], \"type\": \"object\"}}}, {\"type\": \"function\", \"function\": {\"name\": \"send_email\", \"description\": \"Send an email. This cannot be undone.\", \"parameters\": {\"properties\": {\"to\": {\"type\": \"string\"}, \"body\": {\"type\": \"string\"}}, \"required\": [\"to\", \"body\"], \"type\": \"object\"}}}]}", "gen_ai.request.model": "gpt-4o-mini", "totem.llm.in_context": "[{\"ref_type\": \"memory\", \"ref_id\": \"crm/memories/acme.maintenance_schedule\", \"hmac\": \"27419f25ba8d313b096a52ac76f4dc749dbcffa2a90758cb4a5e2caf16af4270\", \"match\": \"exact\", \"spans\": [[0, 638, 706]]}, {\"ref_type\": \"memory\", \"ref_id\": \"crm/memories/acme.new_invoice_address\", \"hmac\": \"c656bc3c9163fca458b7bf342044b15249e1a78a191ce440955191c4df6ebb06\", \"match\": \"exact\", \"spans\": [[0, 735, 764], [3, 433, 462]]}, {\"ref_type\": \"source\", \"ref_id\": \"80a49f98-8630-4f56-9a1c-362b3f54d2e4\", \"hmac\": \"4c5b96e808c7826020fe45ae83efd0e500503ad217b588ac4ecc52f2373e2276\", \"match\": \"exact\", \"spans\": [[1, 0, 164]]}, {\"ref_type\": \"source\", \"ref_id\": \"7318b542-e76a-4d0b-aaba-a2a6b92e731f\", \"hmac\": \"1f11d0b96224e2e8e35622717cfb61a0d9cd6429975fbeb4f5568324a8872409\", \"match\": \"exact\", \"spans\": [[3, 0, 719]]}, {\"ref_type\": \"source\", \"ref_id\": \"71499dce-79a4-44b8-971f-6d6b30fc41b3\", \"hmac\": \"83d91620f7c32291920fb49ff877995b2136308468c02bafeef8afcab88d20eb\", \"match\": \"exact\", \"spans\": [[5, 0, 37]]}, {\"ref_type\": \"source\", \"ref_id\": \"a3ddf2f3-020